using System;using Recovered.Animation;namespace Recovered.Gameplay {public static class PtlRegionVisibility {
  struct N {
   PlaybackWide v;bool neg;bool Zero{get{return v.StoreDouble()==0;}}
   N(PlaybackWide x,bool sign){v=x;double d=x.StoreDouble();neg=d<0||(d==0&&sign);}
   public static N Word(uint w){return new N(PlaybackWide.From(F(w)),(w&0x80000000)!=0);}
   public static N Integer(int i){return new N(PlaybackWide.FromDouble(i),i<0);}
   public static N Add(N a,N b){return new N(PlaybackWide.Add(a.v,b.v),a.Zero&&b.Zero&&a.neg&&b.neg);}
   public static N Sub(N a,N b){return Add(a,new N(PlaybackWide.Multiply(b.v,PlaybackWide.FromDouble(-1)),!b.neg));}
   public static N Mul(N a,N b){return new N(PlaybackWide.Multiply(a.v,b.v),a.neg!=b.neg);}
   public uint Store(){uint w=BitConverter.ToUInt32(BitConverter.GetBytes(v.Store()),0);return Zero&&neg?w|0x80000000:w;}
  }
  static float F(uint w){return BitConverter.ToSingle(BitConverter.GetBytes(w),0);}

static uint Dot(SoundSetupImage m,uint plane,uint[] sphere){N value=N.Add(N.Mul(N.Word(m.Word(plane+4)),N.Word(sphere[1])),N.Mul(N.Word(m.Word(plane)),N.Word(sphere[0])));value=N.Add(value,N.Mul(N.Word(m.Word(plane+8)),N.Word(sphere[2])));return N.Add(value,N.Word(m.Word(plane+12))).Store();}public static uint SphereValues(SoundSetupImage m,uint[] sphere,uint candidate){int count=unchecked((short)m.Half(candidate+0x9c)),outside=0;float radius=F(sphere[3]);if(count>0){uint plane=m.Word(candidate+0x80);for(int i=0;i<count;i++,plane+=16){float distance=F(Dot(m,plane,sphere));if(distance< -radius)return 0;if(distance>radius)outside++;}}float global=F(Dot(m,0x963f78,sphere));if(global< -radius)return 0;if(global>radius)outside++;return outside==count+1?1u:2u;}public static uint Sphere(SoundSetupImage m,uint sphere,uint candidate){return SphereValues(m,new uint[]{m.Word(sphere),m.Word(sphere+4),m.Word(sphere+8),m.Word(sphere+12)},candidate);}public static uint RegionValues(SoundSetupImage m,uint region,uint[] point,uint radius,uint selection){if(m.Word(region+0x6c)==0||unchecked((short)selection)==unchecked((int)m.Word(region+0xe0)))return 1;int count=unchecked((int)m.Word(region+0xdc));uint cursor=region+0x9c;for(int i=0;i<count;i++,cursor+=4){uint candidate=m.Word(cursor);if(candidate==0||m.Half(candidate+0x9e)!=(ushort)selection)continue;uint result=SphereValues(m,new uint[]{point[0],point[1],point[2],radius},candidate);if(result!=0)return result;}return 0;}public static uint Region(SoundSetupImage m,uint region,uint point,uint radius,uint selection){if(m.Word(region+0x6c)==0||unchecked((short)selection)==unchecked((int)m.Word(region+0xe0)))return 1;int count=unchecked((int)m.Word(region+0xdc));uint cursor=region+0x9c;for(int i=0;i<count;i++,cursor+=4){uint candidate=m.Word(cursor);if(candidate==0||m.Half(candidate+0x9e)!=(ushort)selection)continue;uint result=SphereValues(m,new uint[]{m.Word(point),m.Word(point+4),m.Word(point+8),radius},candidate);if(result!=0)return result;}return 0;}}}
